using static TinPan.Localization.Loc;

namespace TinPan.ViewModels
{
    /// <summary>
    /// F1 says one of the short lines for the current tab; Ctrl+F1 shows the full guide.
    /// Each section of the guide is translated on its own. Keep README.md in step with these.
    /// </summary>
    public static class HelpText
    {
        public static string Library => T("Library. Arrow through your songs. Enter plays, Space pauses, Left and Right seek. Applications key for extend, cover, downloads and more. Ctrl+F searches. Ctrl+Shift+F8 resumes where you left off. Alt+F for filters.");

        public static string Create => T("Create. Set the model, style and voice, then describe a song or use your own lyrics. Tab moves between fields. F5 reloads the models.");

        public static string Trending => T("Trending. Enter or Space plays a song. Applications key for more. F5 refreshes.");

        public static string Account => T("Account. Your plan and credits, then Suno's notifications. F2 and Shift+F2 read them from anywhere. F5 refreshes.");

        public static string Playlists => T("Playlists. Pick a playlist and press Enter to open its songs. Enter plays, Space pauses, Delete removes a song, Ctrl+Up and Ctrl+Down move it. Applications key for more on either list.");

        public static string Settings => T("Settings. Sign in or out, choose the language, and choose where songs are saved.");

        public static string NotSignedIn => " " + T("You're not signed in. Ctrl+6 opens Settings.");

        public static string Full => string.Join("\n\n", new[]
        {
            T("Anywhere") + "\n" + T("Alt or F10: the menu bar, hidden until then. Every command is in it, with its keys. Left and Right move between menus, Down opens one, Escape or Alt leaves. The Song menu acts on the song selected in the tab you're on.\nTab only stops on what you need: the search box, the list and the volume. The buttons on each page still work with their Alt letters, and everything is in the menu bar.\nF1: short help for where you are.\nCtrl+F1: all commands in a list; Enter runs one. Its first item is this guide.\nCtrl+R: repeat the last message. Ctrl+Shift+R: message history, newest first.\nEscape: step back one level (to the tab headers, or from a playlist's songs to the playlists).\nF2: credits left.\nShift+F2: your plan, when it renews, credits and downloads left. The Account tab lists everything the plan includes.\nF3: what's playing and how far in.\nF5: refresh the current tab.\nCtrl+1 to Ctrl+6: Library, Playlists, Create, Trending, Account, Settings. Each puts you on that page's list or first field.\nCtrl+F: search your songs."),
            T("Playing") + "\n" + T("F8 or the Play/Pause media key: play or pause; with nothing playing it starts the selected song on the Library or Playlists tab.\nShift+F8: stop.\nF7 and F9: previous and next song.\nShift+F7 and Shift+F9: back and forward 10 seconds.\nCtrl+F7 and Ctrl+F9: back and forward 10 percent of the song.\nCtrl+F8: back to the start of the song.\nCtrl+Shift+F8: resume the last song where you left off, even after closing Tin Pan.\nF11 and F12: volume down and up.\nSongs play through Suno's own player, hidden inside the app."),
            T("Library list") + "\n" + T("Enter: play.\nSpace: pause or resume.\nLeft and Right arrows: back and forward 5 seconds.\nCtrl+I: details (style, model, plays, link and lyrics) as one text.\nAlt+Enter: song information, one fact per line.\nCtrl+L: lyrics.\nCtrl+C: copy the song's link.\nCtrl+D: download in the format chosen in Settings. It uses the song's free unencrypted file when Suno has one; if the direct download fails, the app offers Suno's own download instead.\nCtrl+E: extend.\nDelete: move to Suno trash (asks first).\nApplications key or Shift+F10 for everything: Download WAV, Download video, Extend, Cover, Remaster, Get whole song, Stems, Edit title and lyrics, Make public or private, Add to playlist, Copy Suno share link, Allow or stop remixes, Similar songs, Show comments, Write a comment.\nWAV, Cover and Remaster need a Pro or Premier plan. They're unavailable on the free plan, and say so when the plan isn't known yet.\nReaching the end of the list loads more songs.\nAlt+F, Filters: workspace, disliked songs, trash, stems, Suno Studio songs, liked, public or private, uploaded, covers, extended, remasters, whole songs, personas, songs in a playlist and songs downloaded before. Each can show those songs, show only them, or hide them. Sort newest, oldest, most liked or least liked first. Kept between runs.\nAlt+L, Download all: every finished song in the list, using the free direct download only; songs already in the folder are skipped.\nSongs you liked say \"liked\"."),
            T("Search box") + "\n" + T("Enter searches, Escape clears the search."),
            T("Create tab") + "\n" + T("Model, style, styles to exclude, voice, instrumental, max mode, weirdness, style influence and persona (pick one of yours, or type an ID) apply to both ways of making a song.\nDescribe a song lets Suno write the words. Your own lyrics uses your title and lyrics. Write lyrics makes lyrics from a topic, and Use these lyrics copies them in.\nStyle boost rewrites the Style box into a fuller description.\nChange my lyrics: say what to change, then Rewrite my lyrics now. The result goes into Generated lyrics; Use these lyrics copies it in.\nNew songs appear at the top of your library. You'll hear when they're ready.\nIf Suno asks for a captcha, the app passes it itself. If Suno wants a click, a Suno check window comes forward with the check box."),
            T("Trending tab") + "\n" + T("Loads when you first open it. Enter or Space plays a song; the Applications key has every Song command."),
            T("Account tab") + "\n" + T("Your plan, credits and what the plan includes, then Suno's notifications."),
            T("Playlists tab") + "\n" + T("Left list: your playlists. Enter opens one, Delete moves it to the trash (asks first). New, Rename and Delete buttons.\nRight list: its songs. Enter plays and carries on through the playlist, Space pauses, Delete removes the song from the playlist, Ctrl+Up and Ctrl+Down move it."),
            T("Extend, Cover and Remaster") + "\n" + T("Each opens a short form. Tab moves between fields, Enter on OK starts it, Escape cancels.\nExtend continues a song from a time you choose; then use Get whole song to join the parts.\nCover keeps the melody in a new style; you can change the title and lyrics, which start as the original words, and set audio influence, weirdness, style influence and persona. Remaster makes a cleaner version with a newer model: pick strength (Subtle, Normal, High), kind (Natural, Boost, Clarity) and, if you like, the fine controls."),
            T("Speech") + "\n" + T("Help menu or Settings, Tin Pan speaks: everything; what you ask for and errors (no background news); or only errors and what you ask to hear. F1, F2, F3 and Ctrl+R always speak, and every message is kept in the history.\nSettings, When a list reaches the playing song: a short click (the default), say playing (also in braille), both, or nothing."),
            T("Settings") + "\n" + T("Sign in opens Suno's own sign-in page; it closes by itself once you're in. It remembers your Google account and can save your password. Sign out only signs out of Suno. The first time, or when Suno ends your sign-in, Tin Pan asks you to sign in.\nLanguage: English, Romanian, Ukrainian or Spanish, or the same as Windows. It changes the next time Tin Pan starts.\nDownload folder, download format, and extra files saved next to each download: lyrics, timed lyrics (LRC), song details and cover art.\nCheck for new versions when Tin Pan starts: on by default, and quiet unless there is one."),
            T("Uploading") + "\n" + T("Library menu, Upload a song (Alt+U on the Library page), sends an audio file from this computer to your Suno account, where it becomes a song you can play, extend, cover and remaster. MP3, WAV, M4A, FLAC, AAC and WMA work; anything that isn't M4A is converted to M4A first. You confirm you have the rights to it and accept Suno's upload terms. Suno checks each upload, which can take a minute or two, and may refuse copyrighted music. The length limits are your plan's."),
            T("Clean-up") + "\n" + T("Download (Ctrl+D) asks every time whether to clean the song up with sunscreen, which removes the haze and buzz in Suno songs. Download MP3, Download WAV and Download all don't ask; they clean up when Settings says to. Clean up download, in the Song menu, cleans up a song you already have.\nThe result is a 24-bit WAV next to the download, with (clean) added to its name, often 10 to 20 times bigger. sunscreen reads MP3 and WAV, so Suno's M4A files are converted first. It runs on this computer and takes about 10 seconds for a 5-minute song.\nSettings has each step: decoder buzz, hearing model, flutter, widening, top octave, tone matching and loudness, with their values, and whether to keep the original download."),
            T("Updates") + "\n" + T("Help, Check for updates looks for a new version now. When one is out, Tin Pan says what's new and asks; Yes downloads it, checks its signature, closes Tin Pan, swaps in the new TinPan.exe and opens it again. Saying No at startup means that version isn't offered again by itself.")
        });
    }
}
